INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT143-S1-Q8$batch10$, 143, 1, 8, $batch10$Main Conclusion$batch10$, $batch10$Client: The owners of the catering company we use decided to raise their rates. They argued that the increase was necessary to allow them to hire and train new staff to accommodate their expanding client base. They should reconsider that decision and not raise their rates. After all, the mission of the company is to provide low-cost gourmet catering, and this mission will be jeopardized if they raise rates.$batch10$, $batch10$Which one of the following most accurately expresses the main conclusion of the client’s argument?$batch10$, $batch10$C$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=143 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The owners of the catering company decided to raise their rates.$batch10$, $batch10$Background$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$The catering company needs to increase its rates to accommodate its expanding client base.$batch10$, $batch10$Opposing Point$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The catering company’s rates should not be raised.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The catering company’s mission is to provide low-cost gourmet catering.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$The catering company’s mission will be jeopardized if its rates are increased.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$The owners raised rates, saying they needed to hire and train staff for a growing client base.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$They should reconsider and not raise their rates.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$The company's mission is low-cost gourmet catering, and raising rates would jeopardize it.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"After all" introduces the support, which points back to the sentence before it as the conclusion.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The catering company should not raise its rates.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the decision the client is responding to.$batch10$), ($batch10$B$batch10$, $batch10$This is the owners' reason for the increase, which the client rejects.$batch10$), ($batch10$C$batch10$, $batch10$This is the client's recommendation, the sentence "After all" supports.$batch10$), ($batch10$D$batch10$, $batch10$This is the first part of the support.$batch10$), ($batch10$E$batch10$, $batch10$This completes the support. The mission is in danger, so rates shouldn't go up.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT143-S1-Q8$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
